return ['po-revision-date'=>'2026-01-03 00:36:04+0000','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','x-generator'=>'GlotPress/4.0.3','language'=>'uk_UA','project-id-version'=>'Plugins - Easy WP SMTP – WordPress SMTP and Email Logs: Gmail, Office 365, Outlook, Custom SMTP, and more - Stable (latest release)','messages'=>['"Note" as in "Note: keep this in mind"Note:'=>'Примітка:','%1$s, %2$s'=>'%1$s, %2$s','%1$sFollow this link%2$s to get an API Key for Resend.'=>'%1$sПерейдіть за цим посиланням%2$s, щоб отримати API ключ для Resend.','%d Day'=>'%d день' . "\0" . '%d дні' . "\0" . '%d денів','%s icon'=>'Іконка %s','%s is replaced by "Support Forum" linkHaving issues or difficulties? You can post your issue on the %s'=>'Виникли проблеми чи труднощі? Ви можете опублікувати свою проблему на сайті %s','%s is replaced by "rating" linkLike the plugin? Please give us a %s'=>'Подобається плагін? Дайте нам %s','1 Month'=>'1 місяць','1 Week'=>'1 тиждень','1 Year'=>'1 рік','3 Months'=>'3 місяці','6 Months'=>'6 місяців','API Key'=>'Ключ API','API Key:'=>'Ключ API:','API Keys'=>'API ключі','Access Token'=>'Токен доступу','Actions in this section can (and some of them will) erase or mess up your settings. Use it with caution.'=>'Дії в цьому розділі можуть стерти або зіпсувати ваші налаштування. Використовуйте його обережно.','Activate'=>'Активувати','Add New Group'=>'Додати нову групу','Additional Information'=>'Додаткова інформація','Additional Settings'=>'Додаткові налаштування','Additional Settings (Optional)'=>'Додаткові налаштування (необов\'язково)','Advanced Settings'=>'Розширені налаштування','All'=>'Всі','All settings have been deleted and plugin is deactivated.'=>'Усі налаштування видалено, а плагін вимкнено.','Allow Insecure SSL Certificates'=>'Дозволити небезпечні с